  "scenario_id": "sc-8a9fa1",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2015, 2018],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.16/yr absolute increase in A/E (0.87 to 1.52), peaking at +52% vs expected; empirical SD ~0.22 vs Poisson ~0.05 indicates marked overdispersion",
      "confidence": 0.85,
      "evidence": [
        "ae_death_by_year.csv shows monotonic YoY increase 2015-2018",
        "Empirical SD (~0.22) materially exceeds Poisson expectation (~0.05), confirming overdispersion",
        "2019 drops to 0.734, then stabilizes 0.88-0.95, consistent with trend reversion"
      ],
      "recommended_action": "Investigate 2015-2018 underwriting/pricing/exposure changes driving sustained mortality increase; assess whether 2019 reversion was policy-driven or stochastic; monitor subsequent years for stability; calibrate pricing/valuation models to reflect observed mortality volatility."
    }
  ]
}

